$ cat /usr/local/lib/sklep/funkcje.sh
# Biblioteka funkcji skryptow sklepu - wczytywac przez: source /usr/local/lib/sklep/funkcje.sh
NAZWA_SKRYPTU=${NAZWA_SKRYPTU:-$(basename "$0")}
PLIK_LOGU=${PLIK_LOGU:-/var/log/sklep/skrypty.log}

loguj() {
    printf '%s [%s] %s\n' "$(date '+%F %T')" "$NAZWA_SKRYPTU" "$*" | tee -a "$PLIK_LOGU" >&2
}
zakoncz() {
    loguj "BLAD: $*"
    exit 1
}
czekaj_na_gotowosc() {
    local port=${1:?port} limit=${2:-120} start=$SECONDS
    until curl -fs -m 2 "localhost:$port/actuator/health/readiness" > /dev/null; do
        (( SECONDS - start >= limit )) && return 1
        sleep 2
    done
}
wersja_sklepu() {
    curl -s "localhost:${1:-8080}/actuator/info" | grep -o '"version":"[^"]*"' | cut -d'"' -f4
}
wymagaj_montowania() {
    mountpoint -q "$1" || zakoncz "punkt montowania $1 niedostepny"
}
$ cat ~/bin/pilnuj-sklepu.sh
#!/bin/bash
source /usr/local/lib/sklep/funkcje.sh
for p in 8080 8082; do
    if czekaj_na_gotowosc "$p" 10; then
        loguj "sklep@$p OK, wersja $(wersja_sklepu "$p")"
    else
        loguj "sklep@$p nie odpowiada - restart"
        sudo systemctl restart "sklep@$p"
        czekaj_na_gotowosc "$p" 120 || zakoncz "sklep@$p nie wstal po restarcie"
        loguj "sklep@$p gotowy po restarcie"
    fi
done
